<?php require __DIR__.'/../src/App.php';$u=requireLogin();$c=db();$id=(int)($_GET['id']??0);$r=queryParams($c,'SELECT r.*,p.name project_name FROM releases r JOIN projects p ON p.id=r.project_id WHERE r.id=$1',[(string)$id]);$release=pg_fetch_assoc($r);if(!$release){http_response_code(404);exit('Không tìm thấy phiên bản.');}requireProjectAccess($c,(int)$release['project_id'],$u);$items=pg_fetch_all(queryParams($c,'SELECT * FROM release_items WHERE release_id=$1 ORDER BY id',[(string)$id]))?:[];pageStart('Ghi chú phát hành');?><section class="panel"><p><b>Dự án:</b> <?=h($release['project_name'])?></p><p><b>Phiên bản:</b> <?=h($release['version_name'])?></p><p><?=h($release['description'])?></p><p><span class="pill"><?=h($release['status'])?></span></p><h2>Danh sách thay đổi đã chốt</h2><?php foreach($items as $i):?><article><h3>#<?=$i['issue_id']?> — <?=h($i['snapshot_title'])?></h3><p><?=h($i['snapshot_description'])?></p><p class="muted">Trạng thái khi chốt: <?=h($i['snapshot_status'])?> · Ưu tiên: <?=h($i['snapshot_priority'])?> · Phụ trách: <?=h($i['snapshot_assignee'])?> · Kiểm thử tại thời điểm chốt: <?=h($i['snapshot_test_result'])?></p></article><?php endforeach;?></section><p><button onclick="window.print()">In / Lưu PDF</button> <a class="btn secondary" href="/releases.php?project_id=<?=$release['project_id']?>&id=<?=$id?>">Quay lại</a></p><?php pageEnd(); ?>